//! Wayland protocols without a Smithay frontend: the KDE application menu address protocol
//! (generated by `wayland-protocols-plasma`) and the GTK shell extension (generated here from
//! `protocols/gtk-shell.xml`), both used to learn where a client exports its menus.

use std::sync::Mutex;

use cupertino_wm::Command;
use smithay::reexports::wayland_server::backend::ObjectId;
use smithay::reexports::wayland_server::protocol::wl_surface::WlSurface;
use smithay::reexports::wayland_server::{
    Client, DataInit, Dispatch, DisplayHandle, GlobalDispatch, New, Resource,
};
use wayland_protocols_plasma::appmenu::server::org_kde_kwin_appmenu::{self, OrgKdeKwinAppmenu};
use wayland_protocols_plasma::appmenu::server::org_kde_kwin_appmenu_manager::{
    self, OrgKdeKwinAppmenuManager,
};

use crate::menu_bar::{GtkMenuProps, MenuAddress, MenuKind};
use crate::owner_check::{OwnerCheck, OwnerKey, OwnerRefusal};
use crate::state::Cupertino;

pub mod gtk_shell {
    #![allow(
        dead_code,
        non_camel_case_types,
        unused_unsafe,
        unused_variables,
        non_upper_case_globals,
        non_snake_case,
        unused_imports,
        missing_docs,
        clippy::all
    )]
    use wayland_server;
    use wayland_server::protocol::*;

    pub mod __interfaces {
        use wayland_server::protocol::__interfaces::*;
        wayland_scanner::generate_interfaces!("protocols/gtk-shell.xml");
    }
    use self::__interfaces::*;

    wayland_scanner::generate_server_code!("protocols/gtk-shell.xml");
}

use gtk_shell::gtk_shell1::{self, GtkShell1};
use gtk_shell::gtk_surface1::{self, GtkSurface1};

/// Per-object data: the surface an address belongs to.
pub struct SurfaceData {
    pub surface: WlSurface,
    pub gtk: Mutex<GtkMenuProps>,
}

/// Registers the globals.
pub struct MenuProtocols {
    _appmenu: smithay::reexports::wayland_server::backend::GlobalId,
    _gtk: smithay::reexports::wayland_server::backend::GlobalId,
    /// Bound `gtk_shell1` objects.
    gtk_shells: Vec<GtkShell1>,
    /// The `gtk_shell1` capabilities last sent.
    gtk_capabilities: u32,
}

impl MenuProtocols {
    pub fn new(dh: &DisplayHandle) -> Self {
        Self {
            _appmenu: dh.create_global::<Cupertino, OrgKdeKwinAppmenuManager, ()>(2, ()),
            _gtk: dh.create_global::<Cupertino, GtkShell1, ()>(7, ()),
            gtk_shells: Vec::new(),
            gtk_capabilities: 0,
        }
    }
}

impl GlobalDispatch<OrgKdeKwinAppmenuManager, ()> for Cupertino {
    fn bind(
        _: &mut Self,
        _: &DisplayHandle,
        _: &Client,
        resource: New<OrgKdeKwinAppmenuManager>,
        _: &(),
        init: &mut DataInit<'_, Self>,
    ) {
        init.init(resource, ());
    }
}

impl Dispatch<OrgKdeKwinAppmenuManager, ()> for Cupertino {
    fn request(
        _: &mut Self,
        _: &Client,
        _: &OrgKdeKwinAppmenuManager,
        request: org_kde_kwin_appmenu_manager::Request,
        _: &(),
        _: &DisplayHandle,
        init: &mut DataInit<'_, Self>,
    ) {
        if let org_kde_kwin_appmenu_manager::Request::Create { id, surface } = request {
            init.init(
                id,
                SurfaceData {
                    surface,
                    gtk: Mutex::new(GtkMenuProps::default()),
                },
            );
        }
    }
}

impl Dispatch<OrgKdeKwinAppmenu, SurfaceData> for Cupertino {
    fn request(
        state: &mut Self,
        _: &Client,
        _: &OrgKdeKwinAppmenu,
        request: org_kde_kwin_appmenu::Request,
        data: &SurfaceData,
        _: &DisplayHandle,
        _: &mut DataInit<'_, Self>,
    ) {
        match request {
            org_kde_kwin_appmenu::Request::SetAddress {
                service_name,
                object_path,
            } => {
                state.announce_menu_address(
                    &data.surface,
                    MenuAddress::DbusMenu {
                        service: service_name,
                        path: object_path,
                    },
                );
            }
            org_kde_kwin_appmenu::Request::Release => {
                state.withdraw_menu_address(&data.surface, MenuKind::DbusMenu)
            }
            _ => {}
        }
    }
}

impl GlobalDispatch<GtkShell1, ()> for Cupertino {
    fn bind(
        state: &mut Self,
        _: &DisplayHandle,
        _: &Client,
        resource: New<GtkShell1>,
        _: &(),
        init: &mut DataInit<'_, Self>,
    ) {
        let shell = init.init(resource, ());
        let protocols = &mut state.menu_protocols;
        if protocols.gtk_capabilities != 0 {
            shell.capabilities(protocols.gtk_capabilities);
        }
        protocols.gtk_shells.retain(Resource::is_alive);
        protocols.gtk_shells.push(shell);
    }
}

impl Dispatch<GtkShell1, ()> for Cupertino {
    fn request(
        _: &mut Self,
        _: &Client,
        _: &GtkShell1,
        request: gtk_shell1::Request,
        _: &(),
        _: &DisplayHandle,
        init: &mut DataInit<'_, Self>,
    ) {
        if let gtk_shell1::Request::GetGtkSurface {
            gtk_surface,
            surface,
        } = request
        {
            init.init(
                gtk_surface,
                SurfaceData {
                    surface,
                    gtk: Mutex::new(GtkMenuProps::default()),
                },
            );
        }
    }
}

impl Dispatch<GtkSurface1, SurfaceData> for Cupertino {
    fn request(
        state: &mut Self,
        _: &Client,
        _: &GtkSurface1,
        request: gtk_surface1::Request,
        data: &SurfaceData,
        _: &DisplayHandle,
        _: &mut DataInit<'_, Self>,
    ) {
        match request {
            gtk_surface1::Request::SetDbusProperties {
                application_id,
                app_menu_path,
                menubar_path,
                window_object_path,
                application_object_path,
                unique_bus_name,
            } => {
                let props = GtkMenuProps {
                    bus_name: unique_bus_name.unwrap_or_default(),
                    application_id,
                    application_object_path,
                    window_object_path,
                    menubar_object_path: menubar_path,
                    app_menu_object_path: app_menu_path,
                };
                *data.gtk.lock().expect("gtk props") = props.clone();
                if props.has_menus() && !props.bus_name.is_empty() {
                    state.announce_menu_address(&data.surface, MenuAddress::Gtk(props));
                } else {
                    state.withdraw_menu_address(&data.surface, MenuKind::Gtk);
                }
            }
            gtk_surface1::Request::Present { .. } | gtk_surface1::Request::RequestFocus { .. } => {
                if let Some(id) = state.window_id_for_surface(&data.surface) {
                    state.command(Command::FocusWindow { window: id });
                }
            }
            gtk_surface1::Request::Release => {
                state.withdraw_menu_address(&data.surface, MenuKind::Gtk)
            }
            _ => {}
        }
    }
}

impl Cupertino {
    /// Tell GTK clients whether a menu bar shows their menus: `global_menu_bar` only while the menu bar process has a
    /// bar, so a GTK window hides its own menu bar only when ours takes its place. Call after a bar comes or goes.
    pub fn refresh_gtk_capabilities(&mut self) {
        let capabilities = if self.menu_bars.is_empty() {
            0
        } else {
            gtk_shell1::Capability::GlobalMenuBar as u32
        };
        let protocols = &mut self.menu_protocols;
        if capabilities == protocols.gtk_capabilities {
            return;
        }
        protocols.gtk_capabilities = capabilities;
        protocols.gtk_shells.retain(Resource::is_alive);
        for shell in &protocols.gtk_shells {
            shell.capabilities(capabilities);
        }
    }

    /// A client announced where `surface` exports its menus. The surface has no menus of the address's kind until the
    /// owner of the bus name is checked to be the client or its sandbox instance (`crate::owner_check`); an address of
    /// the other kind stays meanwhile.
    pub fn announce_menu_address(&mut self, surface: &WlSurface, address: MenuAddress) {
        let kind = address.kind();
        self.set_menu_address(surface, kind, None);
        let Some(client) = surface.client() else {
            return;
        };
        let name = address.bus_name().to_owned();
        self.menu_bars.announce(surface, address);
        self.check_owner(OwnerCheck {
            key: OwnerKey::MenuAddress(surface.id(), kind),
            name,
            client,
        });
    }

    /// The client withdrew the menu export of kind `kind` of `surface`.
    pub fn withdraw_menu_address(&mut self, surface: &WlSurface, kind: MenuKind) {
        self.cancel_menu_check(surface, kind);
        self.set_menu_address(surface, kind, None);
    }

    /// `surface` is gone: the checks of its announcements are cancelled.
    pub fn menu_surface_destroyed(&mut self, surface: &WlSurface) {
        self.cancel_menu_check(surface, MenuKind::Gtk);
        self.cancel_menu_check(surface, MenuKind::DbusMenu);
    }

    fn cancel_menu_check(&mut self, surface: &WlSurface, kind: MenuKind) {
        self.menu_bars.take_announced(&surface.id(), kind);
        self.cancel_owner_check(&OwnerKey::MenuAddress(surface.id(), kind));
    }

    /// The check of the latest announcement of kind `kind` of `surface` returned: on a match the address is read from
    /// the owner's unique name; else the surface has no menus of that kind.
    pub(crate) fn menu_owner_checked(
        &mut self,
        surface: ObjectId,
        kind: MenuKind,
        verdict: Result<String, OwnerRefusal>,
    ) {
        let Some((surface, address)) = self.menu_bars.take_announced(&surface, kind) else {
            return;
        };
        if !surface.is_alive() {
            return;
        }
        match verdict {
            Ok(owner) => self.set_menu_address(&surface, kind, Some(address.with_bus_name(owner))),
            Err(refusal) => tracing::warn!(
                name = ?address.bus_name(),
                ?refusal,
                "the bus name a window announced for its menus is not its own: the menu bar is not told of it"
            ),
        }
    }

    /// Set (or withdraw) the menu address of kind `kind` of `surface`; only a checked address is set.
    pub fn set_menu_address(
        &mut self,
        surface: &WlSurface,
        kind: MenuKind,
        address: Option<MenuAddress>,
    ) {
        let root = self
            .root_window_surface(surface)
            .unwrap_or_else(|| surface.clone());
        match self.entry_for_surface(&root).map(|e| e.id.0) {
            Some(key) => self.menu_bars.set_address(key, kind, address),
            None => self.menu_bars.set_pending(surface, kind, address),
        }
        self.refresh_menu_bars();
    }

    /// Apply menu addresses announced before the window mapped.
    pub fn apply_pending_menu_addresses(&mut self, window: u64, root: &WlSurface) {
        for address in self.menu_bars.take_pending(root) {
            self.menu_bars
                .set_address(window, address.kind(), Some(address));
        }
    }
}
